import React, { useEffect, useRef, useState } from 'react';
import { Alert, Button, Card, Spinner } from 'react-bootstrap';
import {
  FaBus,
  FaMapMarkerAlt,
  FaRoute,
  FaSignOutAlt,
} from 'react-icons/fa';
import { saveDriverGpsLocation } from '../../services/TransportServices/transportServices';

function TransportDashboard({ user }) {
  const watchIdRef = useRef(null);
  const lastPositionRef = useRef(null);
  const [gpsEnabled, setGpsEnabled] = useState(false);
  const [gpsBusy, setGpsBusy] = useState(false);
  const [gpsMessage, setGpsMessage] = useState(null);
  const completedStops = Number(user.laststop) || 0;
  const totalStops = Number(user.stpno) || 0;
  const remainingStops = Math.max(totalStops - completedStops, 0);

  useEffect(() => () => {
    if (watchIdRef.current !== null) {
      navigator.geolocation?.clearWatch(watchIdRef.current);
    }
  }, []);

  const sendPosition = async (position, gpssts) => {
    const payload = {
      drvid: user.drvid,
      latitude: position.coords.latitude,
      longitude: position.coords.longitude,
      gpssts,
    };
    const response = await saveDriverGpsLocation(payload);
    if (response?.status !== 'success') {
      throw new Error(response?.error?.message || 'Unable to update GPS location.');
    }
    lastPositionRef.current = position;
  };

  const turnGpsOn = () => {
    if (!user.drvid) {
      setGpsMessage({ variant: 'danger', text: 'Driver ID is not assigned.' });
      return;
    }
    if (!navigator.geolocation) {
      setGpsMessage({ variant: 'danger', text: 'GPS is not supported on this device.' });
      return;
    }
    setGpsBusy(true);
    setGpsMessage(null);
    watchIdRef.current = navigator.geolocation.watchPosition(
      async (position) => {
        try {
          await sendPosition(position, 1);
          setGpsEnabled(true);
          setGpsBusy(false);
          setGpsMessage({ variant: 'success', text: 'GPS tracking is on.' });
        } catch (error) {
          setGpsBusy(false);
          setGpsMessage({ variant: 'danger', text: error.message });
        }
      },
      (error) => {
        setGpsBusy(false);
        setGpsEnabled(false);
        setGpsMessage({ variant: 'danger', text: error.message || 'Location permission denied.' });
      },
      { enableHighAccuracy: true, maximumAge: 10000, timeout: 15000 }
    );
  };

  const turnGpsOff = async () => {
    setGpsBusy(true);
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    try {
      if (lastPositionRef.current) await sendPosition(lastPositionRef.current, 0);
      setGpsEnabled(false);
      setGpsMessage({ variant: 'secondary', text: 'GPS tracking is off.' });
    } catch (error) {
      setGpsMessage({ variant: 'danger', text: error.message });
    } finally {
      setGpsBusy(false);
    }
  };

  const details = [
    {
      label: 'Vehicle',
      value: user.velno || 'Not assigned',
      helper: user.veltyp || 'Vehicle details',
      icon: <FaBus />,
      color: 'cyan',
    },
    {
      label: 'Route',
      value:
        user.frrt || user.tort
          ? `${user.frrt || '—'} → ${user.tort || '—'}`
          : 'Not assigned',
      helper: 'Assigned route',
      icon: <FaRoute />,
      color: 'violet',
    },
    {
      label: 'Stops',
      value: totalStops || '—',
      helper: `${remainingStops} remaining`,
      icon: <FaMapMarkerAlt />,
      color: 'green',
    },
    {
      label: 'Last Stop',
      value: completedStops || 'Not started',
      helper: 'Completed stop number',
      icon: <FaSignOutAlt />,
      color: 'orange',
    },
  ];

  return (
    <div className="dashboard-content">
      <div className="welcome-banner">
        <h2>Good Morning, {user.drvnm || 'Driver'}!</h2>
        <p>Here is your transport assignment for today.</p>
      </div>

      <div className="feed-section">
        <h6 className="feed-title">Today's Transport</h6>
        <Card className="feed-card mb-4">
          <Card.Body>
            <div className="d-flex align-items-center gap-3">
              <span className="dashboard-explore-icon cyan"><FaBus /></span>
              <div>
                <strong>{user.velno || 'No vehicle assigned'}</strong>
                <div className="text-muted small">
                  {user.frrt || 'Route start'} → {user.tort || 'Route end'}
                </div>
              </div>
            </div>
          </Card.Body>
        </Card>

        <Card className="feed-card mb-4">
          <Card.Body>
            <div className="d-flex align-items-center justify-content-between gap-3 flex-wrap">
              <div>
                <strong>GPS Tracking</strong>
                <div className="text-muted small">
                  {gpsEnabled ? 'Your live location is being shared.' : 'GPS tracking is currently off.'}
                </div>
              </div>
              <div className="d-flex gap-2">
                <Button variant="success" onClick={turnGpsOn} disabled={gpsEnabled || gpsBusy}>
                  {gpsBusy && !gpsEnabled ? <Spinner size="sm" animation="border" /> : 'GPS On'}
                </Button>
                <Button variant="outline-danger" onClick={turnGpsOff} disabled={!gpsEnabled || gpsBusy}>
                  GPS Off
                </Button>
              </div>
            </div>
            {gpsMessage && <Alert className="mt-3 mb-0 py-2" variant={gpsMessage.variant}>{gpsMessage.text}</Alert>}
          </Card.Body>
        </Card>

        <div className="dashboard-explore">
          <h6 className="feed-title">Transport Details</h6>
          <div className="dashboard-explore-grid">
            {details.map((item) => (
              <div className="dashboard-explore-item" key={item.label}>
                <span className={`dashboard-explore-icon ${item.color}`}>{item.icon}</span>
                <span>{item.label}</span>
                <small className="text-muted">{item.value}</small>
                <small className="text-muted">{item.helper}</small>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default TransportDashboard;
